ALTER TABLE audit_events ADD COLUMN IF NOT EXISTS correlation_id uuid
  GENERATED ALWAYS AS (
    CASE WHEN (metadata->>'correlation_id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    THEN (metadata->>'correlation_id')::uuid END
  ) STORED;

CREATE OR REPLACE FUNCTION ash_enterprise_audit_immutable() RETURNS trigger AS $fn$
BEGIN
  -- The one DELETE allowed: retention moving a row out of the hot table. The row
  -- must be past the hot floor, and an identical copy must already be archived,
  -- so a row can leave this table only by having arrived there first.
  IF TG_OP = 'DELETE'
     AND OLD.occurred_at < now() - interval '90 days'
     AND EXISTS (
       SELECT 1 FROM audit_event_archive a
       WHERE a.id = OLD.id
         AND (a.sequence, a.organization_id, a.record_id, a.version, a.occurred_at, a.resource, a.action, a.action_type, a.user_id, a.data, a.changed_attributes, a.metadata, a.as_of, a.as_of_range, a.previous_hash, a.hash) IS NOT DISTINCT FROM (OLD.sequence, OLD.organization_id, OLD.record_id, OLD.version, OLD.occurred_at, OLD.resource, OLD.action, OLD.action_type, OLD.user_id, OLD.data, OLD.changed_attributes, OLD.metadata, OLD.as_of, OLD.as_of_range, OLD.previous_hash, OLD.hash)
     ) THEN
    RETURN OLD;
  END IF;

  RAISE EXCEPTION 'audit_events is append-only; % is not permitted', TG_OP
    USING ERRCODE = 'restrict_violation',
          HINT = 'Correct a wrong entry by recording a new one.';
END;
$fn$ LANGUAGE plpgsql;
